from lib import *
S = SS('t11')
steps = [
    step("双写的两种顺序都有问题,用真实的 kill -9 子进程看。A(先写库、再发消息)在两者之间被杀:订单库里有订单 A-1,Kafka 里没有事件——订单已存在、事件丢了,下游永远不知道。B(先发消息、再写库)在两者之间被杀:Kafka 里有事件,订单库里没有订单 B-1——下游看到了一个不存在的订单。数据库和消息队列是两个系统,没有任何东西能让“写库”和“发消息”一起成功或一起失败。", t=tl(S(1)), mark=lidx(S(1), 'A(先写库', 'B(先发消息'), b=bars([['A 被杀后:订单库里的订单', 1, '1'], ['A 被杀后:Kafka 里的事件', 0, '0(丢了)'], ['B 被杀后:订单库里的订单', 0, '0'], ['B 被杀后:Kafka 里的事件', 1, '1(幽灵)']], 1, mark=[1, 3], cur=[0, 2]), kv=KV([['A', '订单有、事件丢'], ['B', '事件有、订单没有'], ['原因', '两个系统没有共同的提交点']], ['原因'])),
    step("Outbox:订单和事件放在同一个本地事务里写(事件写进 outbox 表),应用自己不发消息。应用在提交之后被 kill -9:订单库里有 O-1,outbox 表里有一行 (1, 'O-1', 'OrderCreated', sent=0),Kafka 里还没有。relay 跑一轮,发出 1 条,Kafka 里出现 O-1,outbox 的 sent 标记变成 1。事务如果回滚,订单和 outbox 行一起回滚:回滚后订单库没有 O-2,outbox 也没有 O-2——不会有幽灵事件。", t=tl(S(2)), mark=lidx(S(2), 'kill -9 之后', '回滚之后'), done=lidx(S(2), 'relay 跑一轮'), b=bars([['kill -9 后 outbox 未发的行', 1, '1'], ['relay 之后 Kafka 里的事件', 1, '1'], ['回滚后的订单 / outbox 行数', 0, '0']], 1, mark=[0], done=[1, 2]), kv=KV([['同一个本地事务', '订单 + outbox 一起提交或一起回滚'], ['崩溃之后', 'outbox 里的行还在,relay 补发'], ['回滚', '事件跟着回滚,没有幽灵']], ['同一个本地事务'])),
    step("放大到 1000 单,每一步有 3% 的失败概率。A(先写库再发消息,发布失败率 3%):提交成功 1000 单,Kafka 里只有 966 个不同事件,丢了 34 个。B(先发消息再写库,提交失败率 3%):提交成功 970 单,Kafka 里有 1000 个事件,30 个是没有订单的幽灵事件。Outbox(提交失败率 3%,relay 崩溃 20 次):提交成功 973 单,Kafka 里正好 973 个不同事件,丢 0、幽灵 0,但有 20 条重复投递——relay 在“已发出、未标记”处崩溃,下一轮重发。Outbox 保证不丢、不幽灵,换来的是至少一次的投递。", t=tl(S(3)), mark=lidx(S(3), 'A 先写库再发消息', 'B 先发消息再写库'), done=lidx(S(3), 'Outbox(提交失败率'), b=bars([['A 丢失的事件', 34, '34'], ['B 幽灵事件', 30, '30'], ['Outbox 丢失 + 幽灵', 0, '0'], ['Outbox 重复投递', 20, '20']], 40, mark=[0, 1], done=[2], cur=[3]), kv=KV([['A', '丢 34'], ['B', '幽灵 30'], ['Outbox', '丢 0、幽灵 0、重复 20']], ['Outbox'])),
    step("Outbox 的额外成本:同一个本地事务多写一行。每轮 500 次、3 轮交替共 1500 次,取中位数:只写订单 98 µs,订单加 outbox 一行 137 µs,多 40%。outbox 表 2 万行(payload 约 40 字节的 JSON)占 2.8 MiB,平均每行约 149 字节(含 (sent, id) 索引)。发出去的行如果不清理,表会一直涨。", t=tl(S(4)), mark=lidx(S(4), '订单 + outbox 一行'), done=lidx(S(4), '只写订单:中位数'), b=bars([['只写订单 µs', 98, '98'], ['订单 + outbox µs', 137, '137'], ['outbox 每行字节', 149, '149']], 150, cur=[0], mark=[1], done=[2]), kv=KV([['延迟', '98 µs → 137 µs(+40%)'], ['体积', '每行约 149 字节'], ['清理', '发出去的行要清理']], ['清理'])),
]
A = mkartt('t11', 11, '分布式事务,Outbox,双写,MySQL,Kafka,真实验证,动画演示',
    '实测双写的问题与 Outbox 的修复:kill -9 在两次操作之间,先写库再发消息丢事件、反过来出幽灵事件;1000 单 3% 失败率下 A 丢 34 个、B 幽灵 30 个,Outbox 丢 0、幽灵 0、重复 20 条;写 outbox 多 40% 的延迟,每行约 149 字节。',
    '订单入库后要通知别的服务。先写库再发消息,或者先发消息再写库,都会在两步之间丢东西或多东西。Outbox 把事件和订单放进同一个本地事务。这篇用真实的 MySQL 和 Kafka、真的 kill -9,把双写的问题和 Outbox 的保证与代价量出来。',
    [('34 个 vs 0 个', '1000 单、3% 失败率下,先写库再发消息丢的事件数 vs Outbox 丢的事件数'), ('30 个', '先发消息再写库时,没有对应订单的幽灵事件数'), ('+40%', 'Outbox 在本地事务里多写一行事件带来的延迟(98 µs 到 137 µs)')],
    [('双写的两个方向', '<p>先写库再发消息:进程在两者之间死掉,订单有而事件丢。先发消息再写库:事件有而订单没有。两个系统没有共同的提交点。</p>'),
     ('Outbox', '<p>订单和事件写在同一个本地事务,回滚时一起回滚,提交后即使进程立刻崩溃,事件还在 outbox 表里,relay 补发。</p>'),
     ('规模下的数字', '<p>3% 的失败率,1000 单:A 丢 34 个,B 多 30 个幽灵,Outbox 丢 0、幽灵 0,但 relay 崩溃造成 20 条重复。</p>'),
     ('成本', '<p>多写一行,延迟多 40%,每行约 149 字节,发出去的行要清理。</p>')],
    steps,
    [ENV_T + '。本篇用 MySQL 26.7.0 的 orders / outbox 两张表(outbox 有 (sent, id) 索引)与单节点 KRaft Kafka 4.3.1(brew,topic 单分区);生产者是 confluent-kafka 2.16(幂等生产者,每条 flush);第一、二节的崩溃是 kill -9 子进程,第三节的 3% 失败和 relay 崩溃是用固定种子的随机数在代码里注入的;relay 是我写的轮询程序',
     '没有验证:消费者端怎么处理 relay 造成的重复(第 14、15 篇);outbox 的清理策略和清理对性能的影响;relay 用 CDC 代替轮询(下一篇);payload 更大时的体积与延迟;Kafka 事务(exactly-once)与 outbox 的组合;多个 relay 并发(下一篇)'],
    'Outbox')
